import {
    Box,
    BoxUtil,
    FreBoxProvider,
    FreProjectionHandler,
    FreNodeReference,
    type FreNamedNode,
    BoxFactory,
    LimitedDisplay,
} from "@freon4dsl/core";
import { EventReference, Event, EventState } from "../language/index.js";

import { LanguageEnvironment } from "../index.js";

/**
 * This class implements the box provider for a single node of type EventReference.
 * The box provider is able to create the (tree of) boxes for the node, based
 * on the projections that are currently selected by the user.
 * The top of the tree of boxes is always a box of type ElementBox, which is
 * a box that will never be rendered itself, only its content will. Thus, we
 * have a stable entry in the complete box tree for every FreNode node.
 */
export class EventReferenceBoxProvider extends FreBoxProvider {
    constructor(mainHandler: FreProjectionHandler) {
        super(mainHandler);
        this.knownBoxProjections = ["default", "parser"];
        this.knownTableProjections = ["default"];
        this.conceptName = "EventReference";
    }

    protected getContent(projectionName: string): Box {
        // console.log("GET CONTENT " + this._node?.freId() + ' ' +  this._node?.freLanguageConcept() + ' ' + projectionName);
        // see if we need to use a custom projection
        if (!this.knownBoxProjections.includes(projectionName) && !this.knownTableProjections.includes(projectionName)) {
            const BOX: Box = this.mainHandler.executeCustomProjection(this._node, projectionName);
            if (!!BOX) {
                // found one, so return it
                return BOX;
            }
        } else {
            // select the box to return based on the projectionName
            if (projectionName === "default") {
                return this.getDefault();
            } else if (projectionName === "parser") {
                return this.getParser();
            }
        }
        // in all other cases, return the default
        return this.getDefault();
    }

    private getDefault(): Box {
        return BoxFactory.horizontalLayout(
            this._node as EventReference,
            "EventReference-hlist-line-0",
            "",
            [
                BoxUtil.refReplacerBox(this._node as EventReference, "event", "CustomSelectComponent", {
                    params: [{ key: "placeholder", value: "event reference" }],
                }),
                ,
                BoxUtil.refReplacerBox(this._node as EventReference, "eventState", "CustomSelectComponent", {
                    params: [{ key: "placeholder", value: "event state" }],
                }),
            ],
            { selectable: false },
        );
    }

    private getParser(): Box {
        return BoxFactory.horizontalLayout(
            this._node as EventReference,
            "EventReference-hlist-line-0",
            "",
            [
                BoxUtil.referenceBox(
                    this._node as EventReference,
                    "event",
                    (selected: string | FreNamedNode) => {
                        const ref =
                            typeof selected === "string"
                                ? FreNodeReference.create<Event>(selected, "Event")
                                : FreNodeReference.create<Event>(selected as Event, "Event");
                        (this._node as EventReference).event = ref;
                    },
                    LanguageEnvironment.getInstance().scoper,
                ),
                BoxUtil.limitedBox(
                    this._node as EventReference,
                    "eventState",
                    (selected: string | EventState) => {
                        (this._node as EventReference).eventState = FreNodeReference.create<EventState>(selected, "EventState");
                    },
                    LimitedDisplay.SELECT,
                    LanguageEnvironment.getInstance().scoper,
                ),
            ],
            { selectable: false },
        );
    }
}
